# Generated by manage.py generate_test_cases.
from bloomerp.models.document_templates.document_template import DocumentTemplate
from bloomerp.models.document_templates.document_template_header import (
    DocumentTemplateHeader,
)
from bloomerp.tests.base import BloomerpModelTestCase, ModelScenario


class TestDocumentTemplateModel(BloomerpModelTestCase):
    model = DocumentTemplate

    def prepare_document_template_scenario(self) -> None:
        self.template_header = DocumentTemplateHeader.objects.create(
            name="Scenario header",
            header="document_templates/headers/scenario.png",
        )

    def get_document_template_create_args(self) -> dict:
        return {
            "name": "Scenario template",
            "template_header": self.template_header,
        }

    def validate_created_document_template(
        self, document_template: DocumentTemplate
    ) -> bool:
        return (
            document_template.pk is not None
            and document_template.name == "Scenario template"
            and document_template.template_header_id == self.template_header.pk
        )

    def validate_updated_document_template(
        self, document_template: DocumentTemplate
    ) -> bool:
        return document_template.name == "Updated scenario template"

    def get_test_scenarios(self) -> list[ModelScenario[DocumentTemplate]]:
        return [
            ModelScenario(
                name="Create and rename a document template",
                preparation=self.prepare_document_template_scenario,
                create_args=self.get_document_template_create_args,
                create_validators=self.validate_created_document_template,
                update_args={"name": "Updated scenario template"},
                update_validators=self.validate_updated_document_template,
            ),
        ]
